from django.db import migrations, models


def carry_over_sla_preferences(apps, schema_editor):
    """
    SLA emails are now controlled by one warning and one breach preference, so keep
    them on for installs that had only asked for the first-response ones.
    """
    NotificationSettings = apps.get_model('settings', 'NotificationSettings')
    NotificationSettings.objects.filter(notify_sla_response_warning=True).update(
        notify_sla_resolution_warning=True)
    NotificationSettings.objects.filter(notify_sla_response_breached=True).update(
        notify_sla_resolution_breached=True)


